// Aliases for convenience
FluentIcons.prev = FluentIcons.chevronLeft;
FluentIcons.next = FluentIcons.chevronRight;
FluentIcons.bellRegular = FluentIcons.alertRegular;
FluentIcons.bell = FluentIcons.alertRegular;
FluentIcons.alert = FluentIcons.alertRegular;
FluentIcons.home = FluentIcons.homeRegular;
FluentIcons.search = FluentIcons.searchRegular;
FluentIcons.cart = FluentIcons.cartRegular;
FluentIcons.person = FluentIcons.personRegular;
FluentIcons.receipt = FluentIcons.receiptRegular;
FluentIcons.activity = FluentIcons.receiptRegular;
FluentIcons.activityRegular = FluentIcons.receiptRegular;
FluentIcons.activityFilled = FluentIcons.receiptFilled;
FluentIcons.location = FluentIcons.locationFilled;
FluentIcons.back = FluentIcons.arrowLeft;
FluentIcons.close = FluentIcons.dismiss;
FluentIcons.filterRegular = FluentIcons.optionsRegular;
FluentIcons.filter = FluentIcons.optionsRegular;

// Ensure every SVG string has responsive width and height
for (const key in FluentIcons) {
  if (typeof FluentIcons[key] === 'string' && FluentIcons[key].startsWith('<svg')) {
    if (!FluentIcons[key].includes('width=')) {
      FluentIcons[key] = FluentIcons[key].replace('<svg class="fluent-icon"', '<svg class="fluent-icon" width="1em" height="1em"');
    }
  }
}

function getFluentIcon(name, size = 24, customClass = '') {
  const iconSvg = FluentIcons[name];
  if (!iconSvg) return '';
  return iconSvg.trim()
    .replace('class="fluent-icon"', 'class="fluent-icon ' + customClass + '"')
    .replace('viewBox=', 'width="' + size + '" height="' + size + '" viewBox=');
}
